INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(653593, 68197, 13336, '<td valign="top">ooohh, you took my idea and then took it up a notch!  this is definately a better example of chaos than what i''ve submitted, and might i add a much more attractive photograph.  well done!</td>', 'ooohh, you took my idea and then took it up a notch!  this is definately a better example of chaos than what i''ve submitted, and might i add a much more attractive photograph.  well done!', '2004-04-05 01:05:55.000000', NULL, 1),
(653594, 68226, 15207, '<td valign="top">Finally! Someone gets the point of this challenge - and chose to still take an image that looks artistic, has an interesting and creative point of view, and has balance!<br/>My favorite so far!</td>', 'Finally! Someone gets the point of this challenge - and chose to still take an image that looks artistic, has an interesting and creative point of view, and has balance!My favorite so far!', '2004-04-05 01:06:15.000000', NULL, 1),
(653596, 68157, 772, '<td valign="top">This is a great photo.  I don''t like the way you have used the title to wedge it into the challenge though.. I would have given it a 10 otherwise :)</td>', 'This is a great photo.  I don''t like the way you have used the title to wedge it into the challenge though.. I would have given it a 10 otherwise :)', '2004-04-05 01:07:48.000000', NULL, 1),
(653599, 67987, 15207, '<td valign="top">Congratulations for being one of the few who got the point of this challenge - and captured in a well composed image. Good luck! This one is excellent!</td>', 'Congratulations for being one of the few who got the point of this challenge - and captured in a well composed image. Good luck! This one is excellent!', '2004-04-05 01:08:38.000000', NULL, 1),
(653604, 68185, 15207, '<td valign="top">Excellent! I predict a ribbon!</td>', 'Excellent! I predict a ribbon!', '2004-04-05 01:10:59.000000', NULL, 1),
(653605, 67308, 3102, '<td valign="top">Too digital artsy-ish for my tastes here.</td>', 'Too digital artsy-ish for my tastes here.', '2004-04-05 01:11:41.000000', NULL, 1),
(653606, 68197, 3102, '<td valign="top">Simple, yet complex!  I like this a lot.</td>', 'Simple, yet complex!  I like this a lot.', '2004-04-05 01:12:16.000000', NULL, 1),
(653607, 68172, 3102, '<td valign="top">Good catch!  I like the patterns and the colors you captured here.</td>', 'Good catch!  I like the patterns and the colors you captured here.', '2004-04-05 01:12:40.000000', NULL, 1),
(653609, 68307, 3102, '<td valign="top">One of my favorites of the challenge -- good eye!</td>', 'One of my favorites of the challenge -- good eye!', '2004-04-05 01:12:59.000000', NULL, 1),
(653610, 68161, 15207, '<td valign="top">Love the balance and composition. Nice colours and lighting. Nice to see someone who shot something "messy" but still chose to place things so there is a definite subject - and a place for the eye to move.n Great job!</td>', 'Love the balance and composition. Nice colours and lighting. Nice to see someone who shot something "messy" but still chose to place things so there is a definite subject - and a place for the eye to move.n Great job!', '2004-04-05 01:13:32.000000', NULL, 1),
(653613, 68068, 6804, '<td valign="top">Good Idea, B/W is a good choice for this. I like the position and I am impressed you were able to keep the diagonal lines from showing bitmap. Very nice work.</td>', 'Good Idea, B/W is a good choice for this. I like the position and I am impressed you were able to keep the diagonal lines from showing bitmap. Very nice work.', '2004-04-05 01:15:46.000000', NULL, 1),
(653616, 68007, 6804, '<td valign="top">Impressive selection for "Chaos"    The lights, darks and mid tones all compliment each other nicely. Great angle, high marks for a difficult challenge.</td>', 'Impressive selection for "Chaos"    The lights, darks and mid tones all compliment each other nicely. Great angle, high marks for a difficult challenge.', '2004-04-05 01:19:35.000000', NULL, 1),
(653650, 67898, 16479, '<td valign="top">this one is a real chaos, LOL.....</td>', 'this one is a real chaos, LOL.....', '2004-04-05 01:41:26.000000', NULL, 1),
(653654, 67898, 6888, '<td valign="top">this is truly disgusting</td>', 'this is truly disgusting', '2004-04-05 01:42:18.000000', NULL, 1),
(653655, 67821, 16479, '<td valign="top">nice shot, dof and composition, give you 8.</td>', 'nice shot, dof and composition, give you 8.', '2004-04-05 01:43:17.000000', NULL, 1),
(653663, 67898, 13897, '<td valign="top">This looks like an "out take" from the textures challenge.</td>', 'This looks like an "out take" from the textures challenge.', '2004-04-05 01:53:17.000000', NULL, 1),
(653671, 68185, 6349, '<td valign="top">love this 10</td>', 'love this 10', '2004-04-05 02:02:36.000000', NULL, 1),
(653673, 68185, 12252, '<td valign="top">This is a fun picture. Like the black and white. If I could vote, you''d get an 8 for this one.</td>', 'This is a fun picture. Like the black and white. If I could vote, you''d get an 8 for this one.', '2004-04-05 02:04:57.000000', NULL, 1),
(653675, 68007, 6349, '<td valign="top">one of 2 10''s I gave in the challenge.  Hope this ribbons.  Great work.</td>', 'one of 2 10''s I gave in the challenge.  Hope this ribbons.  Great work.', '2004-04-05 02:06:10.000000', NULL, 1),
(653692, 68226, 6804, '<td valign="top">This certainly is "chaotic." Its also a well shot crystal clear image. I like that it shows an almost systematic, but chaotic organization. Static images are not usually my favorite type of art, but I give this high marks in every way.</td>', 'This certainly is "chaotic." Its also a well shot crystal clear image. I like that it shows an almost systematic, but chaotic organization. Static images are not usually my favorite type of art, but I give this high marks in every way.', '2004-04-05 02:27:37.000000', NULL, 1),
(653693, 68226, 12962, '<td valign="top">Did you sneak into my garage? A ten.</td>', 'Did you sneak into my garage? A ten.', '2004-04-05 02:29:37.000000', NULL, 1),
(653703, 68121, 14863, '<td valign="top">This is really  great- I love the coloring- this better  win! 10</td>', 'This is really  great- I love the coloring- this better  win! 10', '2004-04-05 02:47:48.000000', NULL, 1),
(653706, 68057, 8759, '<td valign="top">It''s not chaotic... It''s beautiful, it''s a pastel. Very good composition and blur effect. 7 (I have a problem with the "meeting the challenge")</td>', 'It''s not chaotic... It''s beautiful, it''s a pastel. Very good composition and blur effect. 7 (I have a problem with the "meeting the challenge")', '2004-04-05 02:50:46.000000', NULL, 1),
(653717, 68165, 14863, '<td valign="top">This is awesome- great job 10</td>', 'This is awesome- great job 10', '2004-04-05 02:53:53.000000', NULL, 1),
(653719, 67898, 14863, '<td valign="top">Ewwwwwwwwwwwwwwwwwwwwwwwwwwwwww! 8 :D</td>', 'Ewwwwwwwwwwwwwwwwwwwwwwwwwwwwww! 8 :D', '2004-04-05 02:54:11.000000', NULL, 1),
(653757, 68267, 14863, '<td valign="top">It''s a  little bright but i think this is  the funniest thing I''ve ever seen! 10 10 10 10 10!!!!!!!!!!!!!!!!!</td>', 'It''s a  little bright but i think this is  the funniest thing I''ve ever seen! 10 10 10 10 10!!!!!!!!!!!!!!!!!', '2004-04-05 03:07:16.000000', NULL, 1),
(653788, 68007, 7602, '<td valign="top">This tree is great!  Excellent photo!</td>', 'This tree is great!  Excellent photo!', '2004-04-05 03:16:10.000000', NULL, 1),
(653833, 68290, 8759, '<td valign="top">It is messy to chaotic. I don''t loke the lightning and the "good for record" taste 5</td>', 'It is messy to chaotic. I don''t loke the lightning and the "good for record" taste 5', '2004-04-05 03:27:01.000000', NULL, 1),
(653864, 67555, 9331, '<td valign="top">This one''s a little dark on my monitor, so much so that it''s a bit hard to see the chess squares. It could have looked even more chaotic, if a piece or two had been knocked over, or some of them weren''t in their squares. Good attempt though at capturing the challenge</td>', 'This one''s a little dark on my monitor, so much so that it''s a bit hard to see the chess squares. It could have looked even more chaotic, if a piece or two had been knocked over, or some of them weren''t in their squares. Good attempt though at capturing the challenge', '2004-04-05 04:02:35.000000', NULL, 1),
(653867, 68212, 9331, '<td valign="top">This is a beautiful photograph, well lit, great colours and sharpness - but too me the flowers look arranged, so not as chaotic as it could have been. Apart from that, I like this photo a lot</td>', 'This is a beautiful photograph, well lit, great colours and sharpness - but too me the flowers look arranged, so not as chaotic as it could have been. Apart from that, I like this photo a lot', '2004-04-05 04:04:40.000000', NULL, 1),
(653869, 68053, 9331, '<td valign="top">WOW - yes this says chaos to me and what a great contrast the birds make against the wood. Well done.</td>', 'WOW - yes this says chaos to me and what a great contrast the birds make against the wood. Well done.', '2004-04-05 04:05:40.000000', NULL, 1),
(653871, 68055, 9331, '<td valign="top">I''d love to know what this is :) Yes - it''s very chaotic, but I wonder how others will rate it though - it''s a tough one, because it doesn''t really look like anything. But due to its chaotic nature, I''ll give it a 7</td>', 'I''d love to know what this is :) Yes - it''s very chaotic, but I wonder how others will rate it though - it''s a tough one, because it doesn''t really look like anything. But due to its chaotic nature, I''ll give it a 7', '2004-04-05 04:08:31.000000', NULL, 1),
(653874, 68007, 9331, '<td valign="top">Interesting shot - bit hard to tell from this, but I wonder if you could have used a directional flash to brighten up the shadows at the top of the photo. It''s just a bit dark compared to the rest of it. Good luck in the challenge</td>', 'Interesting shot - bit hard to tell from this, but I wonder if you could have used a directional flash to brighten up the shadows at the top of the photo. It''s just a bit dark compared to the rest of it. Good luck in the challenge', '2004-04-05 04:10:35.000000', NULL, 1),
(653877, 68309, 9331, '<td valign="top">Very chaotic - but the subject matter is a little uninteresting. Its as though the photo was taken, purely to fit the challenge and not much thought was put in to the artistic side of it. Maybe a few coloured wires, or moving them away from the wall and putting them on a more interesting background could have helped here.</td>', 'Very chaotic - but the subject matter is a little uninteresting. Its as though the photo was taken, purely to fit the challenge and not much thought was put in to the artistic side of it. Maybe a few coloured wires, or moving them away from the wall and putting them on a more interesting background could have helped here.', '2004-04-05 04:14:36.000000', NULL, 1),
(653878, 68267, 8759, '<td valign="top">I like the idea. Is fun. I would have liked a different crop (get rid of the cartboard box) to see more of the boling water</td>', 'I like the idea. Is fun. I would have liked a different crop (get rid of the cartboard box) to see more of the boling water', '2004-04-05 04:15:28.000000', NULL, 1),
(653879, 68313, 9331, '<td valign="top">Very moody shot. Not too fond of the border though - I think I would have preferred the rain drops to go all the way to the edge. Good luck though - it''s a very interesting photo.</td>', 'Very moody shot. Not too fond of the border though - I think I would have preferred the rain drops to go all the way to the edge. Good luck though - it''s a very interesting photo.', '2004-04-05 04:16:04.000000', NULL, 1),
(653881, 68196, 9331, '<td valign="top">This depicts chaos quite adequately. I would have preferred a less tighter crop, and maybe have seen more of the water pouring in from the top of the frame</td>', 'This depicts chaos quite adequately. I would have preferred a less tighter crop, and maybe have seen more of the water pouring in from the top of the frame', '2004-04-05 04:19:14.000000', NULL, 1),
(653883, 68143, 9331, '<td valign="top">Well I hope it''s not this chaotic every time you go out for a date - LOL ;) Did you use flash or just a spotlight on this scene - the centre is well lit, but the light drops off quite dramatically at the sides. Not sure if this was the desired effect or not - but for me, a more even lighting would have looked better.</td>', 'Well I hope it''s not this chaotic every time you go out for a date - LOL ;) Did you use flash or just a spotlight on this scene - the centre is well lit, but the light drops off quite dramatically at the sides. Not sure if this was the desired effect or not - but for me, a more even lighting would have looked better.', '2004-04-05 04:22:09.000000', NULL, 1),
(653885, 68286, 9331, '<td valign="top">Oh my god - I have a drawer just like this one. Great colour, DOF and sharpness. Well done - very chaotic.</td>', 'Oh my god - I have a drawer just like this one. Great colour, DOF and sharpness. Well done - very chaotic.', '2004-04-05 04:23:14.000000', NULL, 1),
(653887, 68310, 9331, '<td valign="top">Nice shot of chaos, but the pole on the right is distracting. Maybe crop just to the left of it and then clone out the overhead wire. Blue looks a tad oversatured in the sky, but it certainly helps bring out the colour in the wall</td>', 'Nice shot of chaos, but the pole on the right is distracting. Maybe crop just to the left of it and then clone out the overhead wire. Blue looks a tad oversatured in the sky, but it certainly helps bring out the colour in the wall', '2004-04-05 04:25:51.000000', NULL, 1),
(653892, 68270, 11800, '<td valign="top">First, I like this a lot.<br/>Everything about this is dreary and muted. Death is a good basis for showing chaos.  The composition is the best that it could be considering the objects within the frame. Because death is the subject and chaos is the theme, a hard focus might have been a better choice, imo.</td>', 'First, I like this a lot.Everything about this is dreary and muted. Death is a good basis for showing chaos.  The composition is the best that it could be considering the objects within the frame. Because death is the subject and chaos is the theme, a hard focus might have been a better choice, imo.', '2004-04-05 04:42:33.000000', NULL, 1),
(653895, 68228, 9331, '<td valign="top">WOW - I really like the effect of this. I would have preferred to have both eyes and the mouth in focus, but then this is your interpretation of chaos, not mine - so I give it a 9</td>', 'WOW - I really like the effect of this. I would have preferred to have both eyes and the mouth in focus, but then this is your interpretation of chaos, not mine - so I give it a 9', '2004-04-05 04:45:22.000000', NULL, 1),
(653897, 68151, 9331, '<td valign="top">Very Blair With Project :) Interesting shot, but the lines are jagged/staircased - especially the diagonals in the top right. Not sure if that was the desired effect, but it detracts from the overal ghostly look a bit for me.</td>', 'Very Blair With Project :) Interesting shot, but the lines are jagged/staircased - especially the diagonals in the top right. Not sure if that was the desired effect, but it detracts from the overal ghostly look a bit for me.', '2004-04-05 04:48:46.000000', NULL, 1),
(653899, 68256, 11800, '<td valign="top">Nice dof detail and composition. The curls on the right are not defined and might have been better cropped out. I think adding more lighting could have helped bring out even more detail within the nest and given a more 3d look to the curls.</td>', 'Nice dof detail and composition. The curls on the right are not defined and might have been better cropped out. I think adding more lighting could have helped bring out even more detail within the nest and given a more 3d look to the curls.', '2004-04-05 04:50:18.000000', NULL, 1),
(653901, 68155, 9331, '<td valign="top">Pity about the dynamic range in this photo - unfortunately, this makes the white dog look washed out and there''s no detail in the black dog. At a guess, it looks as though the shot may have been a bit blurry and you''ve compensated for this by increasing the sharpness to hide it - sharpening artifacts on the black dogs tail and spotted white dots on the door frame seem to have resulted, because of this.</td>', 'Pity about the dynamic range in this photo - unfortunately, this makes the white dog look washed out and there''s no detail in the black dog. At a guess, it looks as though the shot may have been a bit blurry and you''ve compensated for this by increasing the sharpness to hide it - sharpening artifacts on the black dogs tail and spotted white dots on the door frame seem to have resulted, because of this.', '2004-04-05 04:53:35.000000', NULL, 1),
(653902, 68295, 9331, '<td valign="top">Great colours and clarity, along with a well chosen background really give this impact and portray the feeling of chaos very well</td>', 'Great colours and clarity, along with a well chosen background really give this impact and portray the feeling of chaos very well', '2004-04-05 04:55:28.000000', NULL, 1),
(653904, 67987, 9331, '<td valign="top">I''d hate to run in to this intersection :)</td>', 'I''d hate to run in to this intersection :)', '2004-04-05 04:56:55.000000', NULL, 1),
(653905, 67420, 11800, '<td valign="top">Good idea and the composition says chaos. The lighting is interesting. I feel the top part backlighting is too bright. I get the feeling that the front lighting on the one wrench(?) was deliberate but don''t understand the choice. Imo, the whole composition would have benefited with consistant lighting across the entire picture or some lighting applied to the dark wrenches to show a bit of detail.</td>', 'Good idea and the composition says chaos. The lighting is interesting. I feel the top part backlighting is too bright. I get the feeling that the front lighting on the one wrench(?) was deliberate but don''t understand the choice. Imo, the whole composition would have benefited with consistant lighting across the entire picture or some lighting applied to the dark wrenches to show a bit of detail.', '2004-04-05 04:59:03.000000', NULL, 1),
(653906, 68237, 9331, '<td valign="top">Cool shot - it''s not obvious what this is at first glance, so I love the way the photo draws you in to study it in more detail, until you finally realise that its not all chaos and there''s some normality in the background. Hope this does well for you.</td>', 'Cool shot - it''s not obvious what this is at first glance, so I love the way the photo draws you in to study it in more detail, until you finally realise that its not all chaos and there''s some normality in the background. Hope this does well for you.', '2004-04-05 04:59:08.000000', NULL, 1),
(653907, 68195, 9331, '<td valign="top">Unless I had read the title, I wouldn''t have understood how you were trying to portray chaos here. It''s a very nice shot, but unless it can stand on its own legs, without the need for a description, it''s likely to get marked down. I''m giving it a 6 though as it is a very appealing photo</td>', 'Unless I had read the title, I wouldn''t have understood how you were trying to portray chaos here. It''s a very nice shot, but unless it can stand on its own legs, without the need for a description, it''s likely to get marked down. I''m giving it a 6 though as it is a very appealing photo', '2004-04-05 05:01:52.000000', NULL, 1),
(653908, 68128, 9331, '<td valign="top">I''m sooo hungry right now. The raspberry was a nice touch ;)</td>', 'I''m sooo hungry right now. The raspberry was a nice touch ;)', '2004-04-05 05:02:43.000000', NULL, 1),
(653909, 68278, 11800, '<td valign="top">I like your title. Including the tree within the frame helps accent the level of decay of the building.  So, while the picture is of a depressing subject, we are given some hope of renewal. Good balance I''d say.</td>', 'I like your title. Including the tree within the frame helps accent the level of decay of the building.  So, while the picture is of a depressing subject, we are given some hope of renewal. Good balance I''d say.', '2004-04-05 05:03:24.000000', NULL, 1),
(653910, 68219, 9331, '<td valign="top">That''s a lot of fish - I doubt if I could have gotten that close to photograph something like this due to the smell :)</td>', 'That''s a lot of fish - I doubt if I could have gotten that close to photograph something like this due to the smell :)', '2004-04-05 05:03:47.000000', NULL, 1),
(653911, 68316, 8522, '<td valign="top">Doesn''t really say chaos to me... bit too much detail for the eye to take in  though. I feel that the bird which is quite interesting should be the point of focus, but this is not clear.</td>', 'Doesn''t really say chaos to me... bit too much detail for the eye to take in  though. I feel that the bird which is quite interesting should be the point of focus, but this is not clear.', '2004-04-05 05:04:49.000000', NULL, 1),
(653912, 68250, 9331, '<td valign="top">Not sure how you''re trying to indicate chaos here, unless it''s due to the fact that you''ve turned the photo sideways and that the rock should have fallen? If so, perhaps a little deep for me</td>', 'Not sure how you''re trying to indicate chaos here, unless it''s due to the fact that you''ve turned the photo sideways and that the rock should have fallen? If so, perhaps a little deep for me', '2004-04-05 05:06:32.000000', NULL, 1),
(653914, 68212, 8522, '<td valign="top">An interesting shot, doesn''t say Chaos to me personally, but maybe it does if you are a flower arranger! Nice and crisp, although the shallow dof doesn''t seem deliberate enough here. Good colours and saturation. Effective background.</td>', 'An interesting shot, doesn''t say Chaos to me personally, but maybe it does if you are a flower arranger! Nice and crisp, although the shallow dof doesn''t seem deliberate enough here. Good colours and saturation. Effective background.', '2004-04-05 05:06:53.000000', NULL, 1),
(653916, 67308, 8522, '<td valign="top">Too digital art for me... the artifacting around your selection looks very clumsy. Composition and crop don''t work for me. Perhaps a tighter crop to the top and left of your flower would have helped. Flower isn''t sharp enough.</td>', 'Too digital art for me... the artifacting around your selection looks very clumsy. Composition and crop don''t work for me. Perhaps a tighter crop to the top and left of your flower would have helped. Flower isn''t sharp enough.', '2004-04-05 05:09:25.000000', NULL, 1),
(653917, 68124, 9331, '<td valign="top">WHAT THE? Which bar did you go to, to get a shot like this? LOL _ hang on, maybe I don''t want to know? Weird, in a chaotic sort of way :) Good for a laugh at least</td>', 'WHAT THE? Which bar did you go to, to get a shot like this? LOL _ hang on, maybe I don''t want to know? Weird, in a chaotic sort of way :) Good for a laugh at least', '2004-04-05 05:10:07.000000', NULL, 1),
(653918, 68299, 8522, '<td valign="top">Wow, very nice and interesting shot. Not sure a square crop works here, I''d have prefered rectangular. Great textures. Black and white makes this very stark, most people would have colourised this, good decision here not to.</td>', 'Wow, very nice and interesting shot. Not sure a square crop works here, I''d have prefered rectangular. Great textures. Black and white makes this very stark, most people would have colourised this, good decision here not to.', '2004-04-05 05:11:36.000000', NULL, 1),
(653921, 68143, 8522, '<td valign="top">May be chaos, but doesn''t make for a good and pleasing picture.</td>', 'May be chaos, but doesn''t make for a good and pleasing picture.', '2004-04-05 05:12:23.000000', NULL, 1),
(653922, 68299, 9331, '<td valign="top">It doesn''t get much more chaotic than ice and this is a pearler of a shot. The black and white is ok, but I wonder if this could have looked a bit better with a touch of colour</td>', 'It doesn''t get much more chaotic than ice and this is a pearler of a shot. The black and white is ok, but I wonder if this could have looked a bit better with a touch of colour', '2004-04-05 05:12:36.000000', NULL, 1),
(653924, 68287, 8522, '<td valign="top">Fits the bill, but I''d have liked to see a more creative approach to your subject.</td>', 'Fits the bill, but I''d have liked to see a more creative approach to your subject.', '2004-04-05 05:13:21.000000', NULL, 1),
(653925, 68197, 9331, '<td valign="top">Excellent - a definite top 3 I''m sure !!</td>', 'Excellent - a definite top 3 I''m sure !!', '2004-04-05 05:15:04.000000', NULL, 1),
(653926, 68055, 8522, '<td valign="top">Interesting abstract. For me, the textures are a little too uniform throughout the frame for this to be truly compelling, but a nice effect.</td>', 'Interesting abstract. For me, the textures are a little too uniform throughout the frame for this to be truly compelling, but a nice effect.', '2004-04-05 05:15:09.000000', NULL, 1),
(653927, 68310, 11800, '<td valign="top">It looks very deliberate to me. It does have a "riot" of colors though. Get it? The telephone poles don''t add to the composition and might have been avoided if a different angle had been used or some cropping. Aligning the bottom edge of the fence with the bottom edge of the frame might have increased the feeling of displacement.</td>', 'It looks very deliberate to me. It does have a "riot" of colors though. Get it? The telephone poles don''t add to the composition and might have been avoided if a different angle had been used or some cropping. Aligning the bottom edge of the fence with the bottom edge of the frame might have increased the feeling of displacement.', '2004-04-05 05:16:49.000000', NULL, 1),
(653928, 67987, 8522, '<td valign="top">Nice idea, though IMO the background lets you down. I like the arrangement of traffic lights... were they cloned in? The streetlights in the background are very distracting, and I think I''d have liked to see more sky, and buildings in focus in the lower part of the frame.</td>', 'Nice idea, though IMO the background lets you down. I like the arrangement of traffic lights... were they cloned in? The streetlights in the background are very distracting, and I think I''d have liked to see more sky, and buildings in focus in the lower part of the frame.', '2004-04-05 05:17:52.000000', NULL, 1),
(653931, 68068, 11800, '<td valign="top">I like the starkness of the picture and the tangled lines.</td>', 'I like the starkness of the picture and the tangled lines.', '2004-04-05 05:21:10.000000', NULL, 1),
(653932, 67937, 8522, '<td valign="top">Wonderful shot, doesn''t say chaos to me personally though. Maybe it''s because she looks too willing!</td>', 'Wonderful shot, doesn''t say chaos to me personally though. Maybe it''s because she looks too willing!', '2004-04-05 05:21:10.000000', NULL, 1),
(653933, 68191, 9331, '<td valign="top">I''d drop the border - not my taste at all. I like the shot though - 8</td>', 'I''d drop the border - not my taste at all. I like the shot though - 8', '2004-04-05 05:22:54.000000', NULL, 1),
(653934, 68304, 8522, '<td valign="top">May be chaotic, but not an interesting shot for the viewer. Lighting is not condusive to a good picture (shadows, reflections, etc).</td>', 'May be chaotic, but not an interesting shot for the viewer. Lighting is not condusive to a good picture (shadows, reflections, etc).', '2004-04-05 05:22:54.000000', NULL, 1),
(653938, 68257, 9331, '<td valign="top">A nice shot - but perhaps could have been enhanced, by one ant on the leaf, which we could focus our attention on</td>', 'A nice shot - but perhaps could have been enhanced, by one ant on the leaf, which we could focus our attention on', '2004-04-05 05:25:40.000000', NULL, 1),
(653939, 68165, 9331, '<td valign="top">Don''t you mean Dyxlesia?</td>', 'Don''t you mean Dyxlesia?', '2004-04-05 05:26:17.000000', NULL, 1),
