(655880, 68017, 14986, '<td valign="top">It does look messy and chaotic, but really doesn''t appeal to me any other way.</td>', 'It does look messy and chaotic, but really doesn''t appeal to me any other way.', '2004-04-06 18:48:45.000000', NULL, 1),
