(655893, 68191, 6405, '<td valign="top">Don''t like the border.Nuts not in order ,you call it chaos,ok, and I do like the point of view from the bottom up here 6.</td>', 'Don''t like the border.Nuts not in order ,you call it chaos,ok, and I do like the point of view from the bottom up here 6.', '2004-04-06 19:01:43.000000', NULL, 1),
(655897, 68316, 6405, '<td valign="top">Chaos for you is a hunting ground for him!Don''t like the point of view from up down.Grass oversharpened and focal lenghth too wide. 7</td>', 'Chaos for you is a hunting ground for him!Don''t like the point of view from up down.Grass oversharpened and focal lenghth too wide. 7', '2004-04-06 19:04:52.000000', NULL, 1),
(655898, 68287, 6405, '<td valign="top">Reminds me of my last visit to New York.There is no graffiti in Chicago  :-)<br/>It does meet the challenge and is nice photojournalism shot.8</td>', 'Reminds me of my last visit to New York.There is no graffiti in Chicago  :-)It does meet the challenge and is nice photojournalism shot.8', '2004-04-06 19:06:26.000000', NULL, 1),
