(660561, 68227, 19795, '<td valign="top">Beautiful Koi</td>', 'Beautiful Koi', '2004-04-09 00:44:22.000000', NULL, 1),
(660625, 68268, 9668, '<td valign="top">Love the illuminated background. This picture doesn''t really say chaos to me, it seems like a jumble of rocks. But it is a bueatiful jumble of rocks! :)</td>', 'Love the illuminated background. This picture doesn''t really say chaos to me, it seems like a jumble of rocks. But it is a bueatiful jumble of rocks! :)', '2004-04-09 02:31:26.000000', NULL, 1),
(660626, 68299, 9668, '<td valign="top">Cool! This really says chaos to me. I love how it looks metallic. Exposure seems uneven.</td>', 'Cool! This really says chaos to me. I love how it looks metallic. Exposure seems uneven.', '2004-04-09 02:33:51.000000', NULL, 1),
(660628, 67522, 9668, '<td valign="top">Good image, a little small, like the idea of this shot.</td>', 'Good image, a little small, like the idea of this shot.', '2004-04-09 02:37:37.000000', NULL, 1),
(660692, 68165, 6999, '<td valign="top">Neatly done - especially the highlighting of that row of letters, whish is kept within the good dynamic range of the rest of the shot. The barrel distortion is still present, though I think you''ve done well to keep it to a minimum. There isn''t in the end enough appeal in the actual shot, for me - it''s a touch too bluntly only about those letters. Perhaps you might have experimented with other means of framing this one?</td>', 'Neatly done - especially the highlighting of that row of letters, whish is kept within the good dynamic range of the rest of the shot. The barrel distortion is still present, though I think you''ve done well to keep it to a minimum. There isn''t in the end enough appeal in the actual shot, for me - it''s a touch too bluntly only about those letters. Perhaps you might have experimented with other means of framing this one?', '2004-04-09 07:14:53.000000', NULL, 1),
(660693, 68266, 6999, '<td valign="top">Technically lovely photograph - keeps the impression of the dynamic range of the scene without resorting to over-exposure. Good work.</td>', 'Technically lovely photograph - keeps the impression of the dynamic range of the scene without resorting to over-exposure. Good work.', '2004-04-09 07:17:33.000000', NULL, 1),
(660835, 68212, 16230, '<td valign="top">Colorfully chaotic. This is a beautiful photo. A 10 from me.</td>', 'Colorfully chaotic. This is a beautiful photo. A 10 from me.', '2004-04-09 11:31:59.000000', NULL, 1),
(660844, 68007, 16230, '<td valign="top">You have a good eye. Natural chaos well photographed.</td>', 'You have a good eye. Natural chaos well photographed.', '2004-04-09 11:36:40.000000', NULL, 1),
(660850, 67308, 16230, '<td valign="top">Wow, This is very nice. You''ll probably get a bunch of negative comments about the filter use, but I like it. Good job!</td>', 'Wow, This is very nice. You''ll probably get a bunch of negative comments about the filter use, but I like it. Good job!', '2004-04-09 11:39:43.000000', NULL, 1),
(660855, 68228, 16230, '<td valign="top">Terrific photo! Doesn''t hit the challenge criteria nail on the head for me, but I like it very much. I''ll give it an 8.</td>', 'Terrific photo! Doesn''t hit the challenge criteria nail on the head for me, but I like it very much. I''ll give it an 8.', '2004-04-09 11:43:36.000000', NULL, 1),
(660875, 68053, 1024, '<td valign="top">This is the only 10 I have given in this challenge.  Your timing was absolutely perfect!</td>', 'This is the only 10 I have given in this challenge.  Your timing was absolutely perfect!', '2004-04-09 12:02:24.000000', NULL, 1),
(660876, 68270, 1024, '<td valign="top">I love the soft focus, nostalgeic feel of this photo.  It evokes many strong feelings in me, sadness, dispair, and eventually hope.  good luck in the voting.</td>', 'I love the soft focus, nostalgeic feel of this photo.  It evokes many strong feelings in me, sadness, dispair, and eventually hope.  good luck in the voting.', '2004-04-09 12:03:58.000000', NULL, 1),
(660878, 68009, 1024, '<td valign="top">This was a great capture.  Nothing like being in the right place at the right time and actually having your camera ready.  Good luck!</td>', 'This was a great capture.  Nothing like being in the right place at the right time and actually having your camera ready.  Good luck!', '2004-04-09 12:04:53.000000', NULL, 1),
(660881, 68161, 1024, '<td valign="top">This is a very emotive photograph.  The only thing that bothers me is the branch across the foreground.  I think if you would have removed this element,  it would have strengthened the photo.  Good luck!</td>', 'This is a very emotive photograph.  The only thing that bothers me is the branch across the foreground.  I think if you would have removed this element,  it would have strengthened the photo.  Good luck!', '2004-04-09 12:07:28.000000', NULL, 1),
(660882, 68128, 1024, '<td valign="top">There is almost too much in this photo to take in, but I  guess this is the meaning of chaos.  Good luck in the voting!</td>', 'There is almost too much in this photo to take in, but I  guess this is the meaning of chaos.  Good luck in the voting!', '2004-04-09 12:08:38.000000', NULL, 1),
(660884, 68121, 1024, '<td valign="top">So much emotion here.  This photo brings many emotions to the surface, pain, suffering, and a sense of time-less-ness.  Great capture.  Good luck in the voting!</td>', 'So much emotion here.  This photo brings many emotions to the surface, pain, suffering, and a sense of time-less-ness.  Great capture.  Good luck in the voting!', '2004-04-09 12:10:41.000000', NULL, 1),
(660886, 67308, 1024, '<td valign="top">this is too much like digital art for my tastes.</td>', 'this is too much like digital art for my tastes.', '2004-04-09 12:11:26.000000', NULL, 1),
(660889, 68219, 1024, '<td valign="top">LOL, I have seen the fish drying racks in Iceland and this is a great shot from the inside. True chaos!  Good luck in the voting</td>', 'LOL, I have seen the fish drying racks in Iceland and this is a great shot from the inside. True chaos!  Good luck in the voting', '2004-04-09 12:12:39.000000', NULL, 1),
(660892, 68226, 1024, '<td valign="top">This probably shows chaos better than 90% of the photos in this challenge.  I do not envy whoever has to clean up this mess!</td>', 'This probably shows chaos better than 90% of the photos in this challenge.  I do not envy whoever has to clean up this mess!', '2004-04-09 12:13:55.000000', NULL, 1),
(660906, 67898, 12733, '<td valign="top">Yuck, but certainly chaotic.</td>', 'Yuck, but certainly chaotic.', '2004-04-09 12:31:37.000000', NULL, 1),
(660907, 68042, 12733, '<td valign="top">Very nice combination of colors and textures.</td>', 'Very nice combination of colors and textures.', '2004-04-09 12:32:26.000000', NULL, 1),
(660908, 68299, 12733, '<td valign="top">Interesting combination of shapes.</td>', 'Interesting combination of shapes.', '2004-04-09 12:33:17.000000', NULL, 1),
(660910, 68304, 12733, '<td valign="top">The desk meets the challenge. I think the pictures on the wall detract from the effect; could have been cropped in to include just the desk and shelf.</td>', 'The desk meets the challenge. I think the pictures on the wall detract from the effect; could have been cropped in to include just the desk and shelf.', '2004-04-09 12:34:41.000000', NULL, 1),
(660911, 68017, 12733, '<td valign="top">Nice use of controlled motion to create an interesting abastract.</td>', 'Nice use of controlled motion to create an interesting abastract.', '2004-04-09 12:35:12.000000', NULL, 1),
(660913, 67910, 12733, '<td valign="top">I like the combination of shapes, colors and textures. I''m a little put off by the hot spots on the right.</td>', 'I like the combination of shapes, colors and textures. I''m a little put off by the hot spots on the right.', '2004-04-09 12:35:55.000000', NULL, 1),
(660916, 68256, 12733, '<td valign="top">Interesting metallic textures. The relatively short DOF introductes the wrong kind of chaos, too much blur in the background.</td>', 'Interesting metallic textures. The relatively short DOF introductes the wrong kind of chaos, too much blur in the background.', '2004-04-09 12:37:56.000000', NULL, 1),
(660917, 68310, 12733, '<td valign="top">Nice colors - these are not bad artists.</td>', 'Nice colors - these are not bad artists.', '2004-04-09 12:38:27.000000', NULL, 1),
(660918, 67378, 12733, '<td valign="top">I''m not sure what WTF stands for, but the effect is both chaotic and interesting.</td>', 'I''m not sure what WTF stands for, but the effect is both chaotic and interesting.', '2004-04-09 12:39:20.000000', NULL, 1),
(660919, 68157, 12733, '<td valign="top">Nice reflection; you might well have cropped out even more of the boat - possibly all of it - to enhance the effect.</td>', 'Nice reflection; you might well have cropped out even more of the boat - possibly all of it - to enhance the effect.', '2004-04-09 12:40:31.000000', NULL, 1),
(660921, 68314, 12733, '<td valign="top">A chaotic mess. I''m put off by the apparent change in color of the background (table top?).</td>', 'A chaotic mess. I''m put off by the apparent change in color of the background (table top?).', '2004-04-09 12:42:28.000000', NULL, 1),
(660922, 67937, 12733, '<td valign="top">Great capture of the emotion of chaos, along with the appearance.</td>', 'Great capture of the emotion of chaos, along with the appearance.', '2004-04-09 12:43:49.000000', NULL, 1),
(660923, 68228, 11800, '<td valign="top">The colors are appealing. The concept is different.  I don''t like how the effect is so obviously done. The difference between sharp and not sharp is too drastic,imo.</td>', 'The colors are appealing. The concept is different.  I don''t like how the effect is so obviously done. The difference between sharp and not sharp is too drastic,imo.', '2004-04-09 12:45:36.000000', NULL, 1),
(660924, 67336, 12733, '<td valign="top">Nice use of silhouette and sunset. The mood I get from this is peaceful, but I''ll pass on that. The branches could be considered chaotic.</td>', 'Nice use of silhouette and sunset. The mood I get from this is peaceful, but I''ll pass on that. The branches could be considered chaotic.', '2004-04-09 12:45:50.000000', NULL, 1),
(660926, 67522, 12733, '<td valign="top">A truly chaotic tangle of wires makes an interesting abstract. The colored wires add a lot; I would have liked to have seen more of them.</td>', 'A truly chaotic tangle of wires makes an interesting abstract. The colored wires add a lot; I would have liked to have seen more of them.', '2004-04-09 12:47:02.000000', NULL, 1),
(660928, 68267, 12733, '<td valign="top">Interesting idea; I think the egg carton is superfluous and it breaks up the composition.</td>', 'Interesting idea; I think the egg carton is superfluous and it breaks up the composition.', '2004-04-09 12:48:10.000000', NULL, 1),
(660931, 68227, 12733, '<td valign="top">Beautiful capture of beautifully colored fish.</td>', 'Beautiful capture of beautifully colored fish.', '2004-04-09 12:48:55.000000', NULL, 1),
(660935, 68297, 11800, '<td valign="top">I like the title and the picture is easy to look at even if I don''t know what the curls are. I do get a feeling of whatever it is is coming together and that could be a digression. Interesting but not enough information to form an opinion on the intent of the picture.</td>', 'I like the title and the picture is easy to look at even if I don''t know what the curls are. I do get a feeling of whatever it is is coming together and that could be a digression. Interesting but not enough information to form an opinion on the intent of the picture.', '2004-04-09 12:52:09.000000', NULL, 1),
(660939, 68257, 11800, '<td valign="top">That''s a serious ant problem. The dof makes it seem as if the ants do go on forever.  The little tip of new growth on the plant makes me feel sorry for the poor thing yet gives me hope that it will survive the attack. Bugs are often used to portray chaos. Did you see "Jacob''s Ladder"? Anyway. Good luck, this is the best of the bunch I''ve looked at so far.</td>', 'That''s a serious ant problem. The dof makes it seem as if the ants do go on forever.  The little tip of new growth on the plant makes me feel sorry for the poor thing yet gives me hope that it will survive the attack. Bugs are often used to portray chaos. Did you see "Jacob''s Ladder"? Anyway. Good luck, this is the best of the bunch I''ve looked at so far.', '2004-04-09 12:59:03.000000', NULL, 1),
(660943, 68208, 11800, '<td valign="top">Nicely taken. This isn''t something I would naturally consider as chaos. I might be wrong, but wouldn''t it be hard to have music without everyone being organized? The title doesn''t help the picture fit the challenge. Sorry.</td>', 'Nicely taken. This isn''t something I would naturally consider as chaos. I might be wrong, but wouldn''t it be hard to have music without everyone being organized? The title doesn''t help the picture fit the challenge. Sorry.', '2004-04-09 13:06:07.000000', NULL, 1),
(660946, 67308, 11800, '<td valign="top">I don''t think the filter adds to the composition nor does it help define the picture for the challenge.  It is so unnatural that it makes it hard for me to look at it. Sorry.</td>', 'I don''t think the filter adds to the composition nor does it help define the picture for the challenge.  It is so unnatural that it makes it hard for me to look at it. Sorry.', '2004-04-09 13:11:34.000000', NULL, 1),
(660950, 67987, 11800, '<td valign="top">I like it. By cloning the lights multiple times you created a very obvious unrealistic scene that no sane person could take at face value. The buildings in the background add a false note of security that makes the lights seem even more cruel.  The title is neutral enough to tie the whole thing together.</td>', 'I like it. By cloning the lights multiple times you created a very obvious unrealistic scene that no sane person could take at face value. The buildings in the background add a false note of security that makes the lights seem even more cruel.  The title is neutral enough to tie the whole thing together.', '2004-04-09 13:20:06.000000', NULL, 1),
(660961, 67555, 11800, '<td valign="top">I think that chaos implies unorganized, in dissarray, out of control, etc. Seems to me that chess is totally organized. I could be wrong though.</td>', 'I think that chaos implies unorganized, in dissarray, out of control, etc. Seems to me that chess is totally organized. I could be wrong though.', '2004-04-09 13:44:39.000000', NULL, 1),
(660970, 68135, 11800, '<td valign="top">I like the complex layering of the transparencies. The grain adds to the overall effect.</td>', 'I like the complex layering of the transparencies. The grain adds to the overall effect.', '2004-04-09 13:51:58.000000', NULL, 1),
(661090, 68226, 18709, '<td valign="top">This is very good. Truly chaotic.</td>', 'This is very good. Truly chaotic.', '2004-04-09 16:38:35.000000', NULL, 1),
(661095, 68135, 18709, '<td valign="top">I don''t think I LIKE this very much , but there is a great deal to admire.</td>', 'I don''t think I LIKE this very much , but there is a great deal to admire.', '2004-04-09 16:41:05.000000', NULL, 1),
(661096, 68142, 18709, '<td valign="top">A neglected corner of somebody''s backyard?  The black and  w hite helps.</td>', 'A neglected corner of somebody''s backyard?  The black and  w hite helps.', '2004-04-09 16:42:08.000000', NULL, 1);
