(663555, 68151, 7684, '<td valign="top">Thank you for all the comments. I think this shot did pretty well since it is taken with a very cheap $20- digital camera. The camera is only 0.3 mega pixels and I added no special effect to the shot only changed to black and white in photoshop and added contrast.</td>', 'Thank you for all the comments. I think this shot did pretty well since it is taken with a very cheap $20- digital camera. The camera is only 0.3 mega pixels and I added no special effect to the shot only changed to black and white in photoshop and added contrast.', '2004-04-12 07:39:23.000000', NULL, 0),
(663556, 68053, 6624, '<td valign="top">stunning</td>', 'stunning', '2004-04-12 07:39:33.000000', NULL, 0),
